/*
 * Primitives: the raw scale. Every value in the product comes from here.
 *
 * For agents:
 * - Take values from this file; never invent one (no 13.5px, no 10px gap, no new hex).
 * - Components never use these directly. They use the semantic tokens in semantic.css.
 * - A value marked `@decide` is not settled. Ask the person before using or changing it.
 *   `node checks/check-tokens.mjs --decisions` lists them.
 */

:root {
  /* Color: neutral scale */
  --gray-0: #ffffff;
  --gray-50: #fafafa;
  --gray-100: #f4f4f5;
  --gray-200: #e4e4e7;
  --gray-300: #d4d4d8;
  --gray-400: #a1a1aa;
  --gray-500: #71717a;
  --gray-600: #52525b;
  --gray-700: #3f3f46;
  --gray-800: #27272a;
  --gray-900: #18181b;
  --gray-950: #09090b;

  /* Color: meaning. Used only through status and action tokens, never as decoration. */
  --blue-500: #3b82f6;
  --blue-600: #2563eb;
  --green-500: #22c55e;
  --green-700: #15803d;
  --amber-500: #f59e0b;
  --amber-700: #b45309;
  --red-500: #ef4444;
  --red-600: #dc2626;

  /* @decide: the product's accent (brand) colour. Ask before choosing one. */
  --accent-500: var(--blue-500);

  /* Type */
  /* @decide: the product's typefaces. */
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --text-xs: 12px;
  --text-sm: 13px;
  --text-base: 14px;
  --text-lg: 16px;
  --text-xl: 20px;
  --text-2xl: 24px;
  --text-3xl: 32px;
  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --leading-tight: 1.25;
  --leading-normal: 1.5;
  --tracking-tight: -0.02em;

  /* Spacing: a 4px grid */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;

  /* Shadow */
  --shadow-sm: 0 1px 2px rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 12px rgb(0 0 0 / 0.08);
  --shadow-lg: 0 12px 32px rgb(0 0 0 / 0.12);

  /* Motion */
  --ease-smooth: cubic-bezier(0.22, 1, 0.36, 1);
  --duration-fast: 150ms;
  --duration-normal: 200ms;
  --duration-slow: 300ms;

  /* Sizes */
  --size-icon-sm: 14px;
  --size-icon-md: 16px;
  --size-control-sm: 32px;
  --size-control-md: 36px;
  --size-control-touch: 44px;
  --width-content: 1200px;
  --width-reading: 720px;

  /* Layers */
  --layer-sticky: 10;
  --layer-dropdown: 20;
  --layer-overlay: 40;
  --layer-dialog: 50;
  --layer-toast: 60;
}

/*
 * Semantic tokens: what a value is for, not what it looks like. Components use only these
 * (directly or through the Tailwind names in tailwind.css). Each points back to a primitive.
 *
 * Light and dark live together through light-dark(): the first value is light, the second dark.
 * The theme follows the system; set data-theme="light" or "dark" on <html> to force one.
 *
 * Colour carries meaning. Green, amber, red and blue appear only through the status tokens,
 * for a real state (done, needs a look, failed, running), never to decorate.
 */

:root { color-scheme: light dark; }
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] { color-scheme: dark; }

:root {
  /* Surface */
  --bg-app: light-dark(var(--gray-50), var(--gray-950));
  --bg-surface: light-dark(var(--gray-0), var(--gray-900));
  --bg-subtle: light-dark(var(--gray-100), var(--gray-800));
  --bg-hover: light-dark(var(--gray-100), var(--gray-800));
  --bg-pressed: light-dark(var(--gray-200), var(--gray-700));
  --bg-selected: light-dark(var(--gray-100), var(--gray-800));
  --border-default: light-dark(var(--gray-200), var(--gray-800));
  --border-strong: light-dark(var(--gray-300), var(--gray-700));

  /* Text */
  --text-primary: light-dark(var(--gray-900), var(--gray-50));
  --text-secondary: light-dark(var(--gray-700), var(--gray-300));
  --text-muted: light-dark(var(--gray-500), var(--gray-400));
  --text-disabled: light-dark(var(--gray-400), var(--gray-600));

  /* Action: one primary per screen */
  --action-primary: light-dark(var(--gray-900), var(--gray-50));
  --action-primary-text: light-dark(var(--gray-0), var(--gray-900));
  --action-accent: var(--accent-500);
  --focus-ring: var(--blue-500);

  /* Status: each tone is a set, so a badge, banner or dot never mixes its own.
     The ink is darker on light backgrounds so text and icons stay readable (4.5:1). */
  --status-success: light-dark(var(--green-700), var(--green-500));
  --status-success-bg: color-mix(in oklch, var(--green-500) 12%, transparent);
  --status-success-border: color-mix(in oklch, var(--green-500) 30%, transparent);
  --status-warning: light-dark(var(--amber-700), var(--amber-500));
  --status-warning-bg: color-mix(in oklch, var(--amber-500) 12%, transparent);
  --status-warning-border: color-mix(in oklch, var(--amber-500) 30%, transparent);
  --status-error: light-dark(var(--red-600), var(--red-500));
  --status-error-bg: color-mix(in oklch, var(--red-500) 12%, transparent);
  --status-error-border: color-mix(in oklch, var(--red-500) 30%, transparent);
  --status-running: light-dark(var(--blue-600), var(--blue-500));
  --status-running-bg: color-mix(in oklch, var(--blue-500) 12%, transparent);
  --status-running-border: color-mix(in oklch, var(--blue-500) 30%, transparent);
  --status-neutral: var(--text-muted);
  --status-neutral-bg: var(--bg-subtle);
  --status-neutral-border: var(--border-default);

  /* Type roles */
  --family-ui: var(--font-sans);
  --family-code: var(--font-mono);
  --size-meta: var(--text-xs);
  --size-label: var(--text-sm);
  --size-body: var(--text-base);
  --size-section: var(--text-lg);
  --size-title: var(--text-2xl);
  --size-display: var(--text-3xl);

  /* Layout */
  --gap-inline: var(--space-2);
  --gap-stack: var(--space-4);
  --gap-section: var(--space-8);
  --padding-control: var(--space-3);
  --padding-card: var(--space-4);
  --padding-page: var(--space-8);
  --padding-page-compact: var(--space-4);
  --shape-control: var(--radius-full);
  --shape-card: var(--radius-lg);
  --shape-row: var(--radius-md);

  /* Elevation */
  --elevation-card: var(--shadow-sm);
  --elevation-popover: var(--shadow-md);
  --elevation-dialog: var(--shadow-lg);

  /* Motion */
  --motion-hover: var(--duration-fast) var(--ease-smooth);
  --motion-enter: var(--duration-normal) var(--ease-smooth);
  --motion-panel: var(--duration-slow) var(--ease-smooth);
}

/*
 * Points shadcn/ui's own variables at the semantic tokens, so every shadcn component follows
 * the foundation without being restyled. Replaces the colour block `shadcn init` writes.
 */

:root {
  --background: var(--bg-app);
  --foreground: var(--text-primary);
  --card: var(--bg-surface);
  --card-foreground: var(--text-primary);
  --popover: var(--bg-surface);
  --popover-foreground: var(--text-primary);
  --primary: var(--action-primary);
  --primary-foreground: var(--action-primary-text);
  --secondary: var(--bg-subtle);
  --secondary-foreground: var(--text-primary);
  --muted: var(--bg-subtle);
  --muted-foreground: var(--text-muted);
  --accent: var(--bg-hover);
  --accent-foreground: var(--text-primary);
  --destructive: var(--status-error);
  --border: var(--border-default);
  --input: var(--border-default);
  --ring: var(--focus-ring);
  --radius: var(--radius-lg);
}

/*
 * Tailwind v4 names for the semantic tokens, so components write `bg-surface text-ink-muted
 * rounded-card` instead of raw values. Import after primitives.css and semantic.css:
 *
 *   @import "tailwindcss";
 *   @import "./foundation/primitives.css";
 *   @import "./foundation/semantic.css";
 *   @import "./foundation/shadcn.css";
 *   @import "./foundation/tailwind.css";
 *
 * Names avoid shadcn's own (`primary`, `secondary`, `muted`, `accent`), which mean something
 * else there: text colours are `ink-*`, the brand colour is `brand`.
 * Tailwind's default palette (gray-500, red-500…) fails the token check inside components.
 */

@theme inline {
  --color-app: var(--bg-app);
  --color-surface: var(--bg-surface);
  --color-subtle: var(--bg-subtle);
  --color-hover: var(--bg-hover);
  --color-pressed: var(--bg-pressed);
  --color-selected: var(--bg-selected);
  --color-line: var(--border-default);
  --color-line-strong: var(--border-strong);

  --color-ink: var(--text-primary);
  --color-ink-secondary: var(--text-secondary);
  --color-ink-muted: var(--text-muted);
  --color-ink-disabled: var(--text-disabled);

  --color-action: var(--action-primary);
  --color-action-text: var(--action-primary-text);
  --color-brand: var(--action-accent);
  --color-focus: var(--focus-ring);

  --color-success: var(--status-success);
  --color-success-bg: var(--status-success-bg);
  --color-success-line: var(--status-success-border);
  --color-warning: var(--status-warning);
  --color-warning-bg: var(--status-warning-bg);
  --color-warning-line: var(--status-warning-border);
  --color-error: var(--status-error);
  --color-error-bg: var(--status-error-bg);
  --color-error-line: var(--status-error-border);
  --color-running: var(--status-running);
  --color-running-bg: var(--status-running-bg);
  --color-running-line: var(--status-running-border);
  --color-neutral: var(--status-neutral);
  --color-neutral-bg: var(--status-neutral-bg);
  --color-neutral-line: var(--status-neutral-border);

  --font-ui: var(--family-ui);
  --font-code: var(--family-code);

  --text-meta: var(--size-meta);
  --text-label: var(--size-label);
  --text-body: var(--size-body);
  --text-section: var(--size-section);
  --text-title: var(--size-title);
  --text-display: var(--size-display);

  --radius-control: var(--shape-control);
  --radius-card: var(--shape-card);
  --radius-row: var(--shape-row);

  --shadow-card: var(--elevation-card);
  --shadow-popover: var(--elevation-popover);
  --shadow-dialog: var(--elevation-dialog);
}
